/** Returns the deep blueprint for a pack id, or undefined for packs not yet upgraded. */
export function getPackBlueprint(packId: string): PackBlueprint | undefined {
  return PACK_BLUEPRINTS[packId];
}

/** True when a pack has a deep blueprint (vs. the legacy team-only seeding). */
export function hasPackBlueprint(packId: string): boolean {
  return packId in PACK_BLUEPRINTS;
}

export interface PackSummary {
  packId: string;
  title: string;
  emoji: string;
  tagline: string;
  tier: PackTier;
  teamCount: number;
  taskCount: number;
  docCount: number;
  frameworkCount: number;
  field: string | null;
  direction: BlueprintDirection;
}

/** Compact, client-safe summary of one blueprint (for the picker cards + router response). */
export function summarizeBlueprint(bp: PackBlueprint): PackSummary {
  return {
    packId: bp.packId,
    title: bp.packTitle,
    emoji: bp.emoji,
    tagline: bp.tagline,
    tier: bp.tier,
    teamCount: bp.team.length,
    taskCount: bp.tasks.length,
    docCount: bp.documents.length,
    frameworkCount: bp.playbook?.frameworks.length ?? 0,
    field: bp.playbook?.field ?? null,
    direction: bp.direction,
  };
}

/** All deep packs as summaries — powers the pack catalog endpoint + the picker cards. */
export function packCatalog(): PackSummary[] {
  return Object.values(PACK_BLUEPRINTS).map(summarizeBlueprint);
}

/** Tier for a pack id; deep packs carry their own tier, unknown/legacy packs default to free. */
export function getPackTier(packId: string): PackTier {
  return PACK_BLUEPRINTS[packId]?.tier ?? "free";
}

// -----------------------------------------------------------------------------
// Pack detail (BIAB UI — the "inside a pack" screen, 2026-08-11)
// A client-safe, presentation-oriented view of a blueprint: the team grouped by
// department, the field frameworks, the documents, and the plan grouped by stage.
// Powers GET /api/packs/:packId. Structural data only (no invented stats).
// -----------------------------------------------------------------------------

/** Maps a roleRegistry role to a plain-language department, so the team reads like a company.
 *  Kept coarse (~6 buckets) so the "Your team" grouping stays tidy, not fragmented. */
const ROLE_DEPARTMENT: Record<string, string> = {
  "Product Manager": "Product & engineering",
  "Business Analyst": "Product & engineering",
  "Technical Lead": "Product & engineering",
  "Backend Developer": "Product & engineering",
  "Software Engineer": "Product & engineering",
  "AI Developer": "Product & engineering",
  "DevOps Engineer": "Product & engineering",
  "UI Engineer": "Product & engineering",
  "QA Lead": "Product & engineering",
  "Product Designer": "Design & brand",
  "UX Designer": "Design & brand",
  "UI Designer": "Design & brand",
  "Designer": "Design & brand",
  "Creative Director": "Design & brand",
  "Brand Strategist": "Design & brand",
  "Growth Marketer": "Marketing & growth",
  "Marketing Specialist": "Marketing & growth",
  "SEO Specialist": "Marketing & growth",
  "Email Specialist": "Marketing & growth",
  "Content Writer": "Marketing & growth",
  "Copywriter": "Marketing & growth",
  "Social Media Manager": "Marketing & growth",
  "Instructional Designer": "Marketing & growth",
  "Audio Editor": "Marketing & growth",
  "Finance Analyst": "Money & legal",
  "Legal Counsel": "Money & legal",
  "Data Analyst": "Data",
  "Data Scientist": "Data",
  "Operations Manager": "Operations",
  "HR Specialist": "Operations",
  "Business Strategist": "Strategy",
  "Sales Lead": "Sales & success",
  "Customer Success Manager": "Sales & success",
};

/** Department for a role, falling back to a sensible default. */
export function departmentForRole(role: string): string {
  return ROLE_DEPARTMENT[role] ?? "Team";
}

const CHARACTER_NAME_BY_ROLE = new Map(ROLE_DEFINITIONS.map((r) => [r.role, r.characterName]));

/** The cast character name for a role (Alex, Cleo, Juhi…), same resolver the seeder uses. */
export function characterNameForRole(role: string): string {
  return CHARACTER_NAME_BY_ROLE.get(role) ?? role;
}

export interface PackDetailMember {
  role: string;
  /** The cast character name (Alex, Cleo, Juhi…) — matches what gets seeded. */
  name: string;
  department: string;
  brief: string;
}
export interface PackDetailDoc {
  key: string;
  title: string;
  type: string;
  role: string;
  stage: LifecycleStage;
}
export interface PackDetailStep {
  title: string;
  role: string;
  producesDocKey?: string;
}
export interface PackDetailStage {
  key: LifecycleStage;
  label: string;
  summary: string;
  steps: PackDetailStep[];
}
export interface PackDetail {
  packId: string;
  title: string;
  emoji: string;
  tagline: string;
  tier: PackTier;
  field: string | null;
  direction: BlueprintDirection;
  stats: { team: number; steps: number; docs: number; frameworks: number };
  team: PackDetailMember[];
  frameworks: string[];
  /** Frameworks grouped into plain themes for the UI; empty when the pack has no groups. */
  playbookGroups: { label: string; frameworks: string[] }[];
  /** Plain-language one-liner per framework (for tooltips); empty when none authored. */
  playbookGlosses: Record<string, string>;
  /** Roles that join "as you scale" (display-only, not seeded). */
  addOnRoles: string[];
  documents: PackDetailDoc[];
  plan: PackDetailStage[];
}

/** Full, client-safe detail for the "inside a pack" screen. Returns undefined for legacy packs. */
export function packDetail(packId: string): PackDetail | undefined {
  const bp = PACK_BLUEPRINTS[packId];
  if (!bp) return undefined;
  return {
    packId: bp.packId,
    title: bp.packTitle,
    emoji: bp.emoji,
    tagline: bp.tagline,
    tier: bp.tier,
    field: bp.playbook?.field ?? null,
    direction: bp.direction,
    stats: {
      team: bp.team.length,
      steps: bp.tasks.length,
      docs: bp.documents.length,
      frameworks: bp.playbook?.frameworks.length ?? 0,
    },
    team: bp.team.map((role) => ({
      role,
      name: characterNameForRole(role),
      department: departmentForRole(role),
      brief: bp.roleBriefs[role] ?? "",
    })),
    frameworks: bp.playbook?.frameworks ?? [],
    playbookGroups: bp.playbook?.groups ?? [],
    playbookGlosses: bp.playbook?.glosses ?? {},
    addOnRoles: bp.addOnRoles ?? [],
    documents: bp.documents.map((d) => ({ key: d.key, title: d.title, type: d.type, role: d.role, stage: d.stage })),
    plan: bp.stages.map((s) => ({
      key: s.key,
      label: s.label,
      summary: s.summary,
      steps: bp.tasks
        .filter((t) => t.stage === s.key)
        .map((t) => ({ title: t.title, role: t.role, producesDocKey: t.producesDocKey })),
    })),
  };
}
